// DUT Instantiation for Controller 1, streaming configuration. CTRL1_GT_0 has
// LINK1_WIDTH lanes (X2 or X8, the CED's CTRL_LINK_WIDTH option; the Makefile
// reads it from defines.sv and passes it to tb_top as LINK1_WIDTH).
//
// Connects to the shared tb_top.sv, which declares scalar-suffixed
// vip2dut_1_p/n, dut2vip_1_p/n, refclk_1_p/n signals.
//
// Instantiates ctrl1_qdma_st_ep_sim_wrapper (generated by Vivado at
// launch_simulation time), NOT ctrl1_qdma_st_ep directly. The sim_wrapper
// adds the xlnoc instance and its npp_in/npp_out wiring into axi_noc2_0;
// without it the NoC Packet Protocol ports are left floating and the
// axi_noc2_0 NMU's protection checker stops the simulation at time zero.
// The sim_wrapper has the same external port list as ctrl1_qdma_st_ep, so it
// is a drop-in replacement.
//
// Only the GT lanes and their reference clock cross the top-level boundary;
// the streaming example design (H2C sinks, C2H sources, completion
// generators, descriptor-credit logic) sits inside ctrl1_qdma_st_ep.

generate
  if (tb_top.LINK1_WIDTH != 0) begin : ctrl_inst
    ctrl1_qdma_st_ep_sim_wrapper dut_inst (
        .CTRL1_GT_0_grx_n        ( vip2dut_1_n[LINK1_WIDTH-1:0] ),
        .CTRL1_GT_0_grx_p        ( vip2dut_1_p[LINK1_WIDTH-1:0] ),
        .CTRL1_GT_0_gtx_n        ( dut2vip_1_n[LINK1_WIDTH-1:0] ),
        .CTRL1_GT_0_gtx_p        ( dut2vip_1_p[LINK1_WIDTH-1:0] ),

        .ctrl1_gt_refclk_0_clk_n ( refclk_1_n ),
        .ctrl1_gt_refclk_0_clk_p ( refclk_1_p )
    );
  end
endgenerate
